async def generate():
    print("Generating diacritized podcasts...")
    for pod in podcasts:
        print(f"Generating {pod['file']}...")
        communicate = edge_tts.Communicate(pod['text'], VOICE)
        await communicate.save(pod['file'])
    print("Done!")

if __name__ == "__main__":
    asyncio.run(generate())
